class Item {
    final String name;
    final int qty;
    private Item(Builder b) { name = b.name; qty = b.qty; }
    static class Builder {
        String name; int qty = 1;
        Builder(String name) { this.name = name; }
        Builder qty(int q) { qty = q; return this; }
        Item build() { return new Item(this); }
    }
}
public class Main {
    public static void main(String[] args) {
        Item i = new Item.Builder("Rune").qty(5).build();
        System.out.println(i.name + " x" + i.qty);
    }
}

static class Builder {
    String name;
    int power;
    public Builder name(String name) { this.name = name; }
    public Builder power(int power) { this.power = power; }
    public Spell build() { return new Spell(this); }
}
